    MapEntry(RegExp(r'овал и полукруг|межбуквенных|широкой косой|микрографи|скоропись|скорость письма|самопроверка почерка|широкую строку'), 'pen_mazina_advanced'),
  ];

  static String _matchCategory(String topic, String subject) {
    final t = topic.toLowerCase();
    for (final entry in _categoryPatterns) {
      if (entry.key.hasMatch(t)) return entry.value;
    }
    final s = subject.toLowerCase();
    if (s.contains('матем')) return 'math_addition_subtraction_10';
    if (s.contains('чтен')) return 'read_sound_analysis';
    if (s.contains('чистопис') || s.contains('письм')) return 'pen_slant_grid';
    return 'ru_sounds_letters';
  }

  static PedagogicalPackage _buildPackage(String category, String topic, String ageGroup) {
    switch (category) {
      case 'ru_sounds_letters':
        return const PedagogicalPackage(
          category: 'ru_sounds_letters',
          essence: 'Звуки — это звучащая материя языка, то, что мы произносим и слышим ухом. Буквы — это графические значки, которыми звуки записываются в тетради (мы их видим и пишем). Гласные звуки поются чистым голосом, выдыхаемый воздух не встречает во рту никаких преград [а, о, у, ы, и, э]. Согласные звуки обязательно преодолевают преграду — смыкание губ, зубов или прижатие язычка [б, п, м, с, к]. Именно поэтому гласные тянутся, как песня, а согласные шуршат, свистят или стучат.',
          metaphors: [
            'Гласные — это чистые звонкие ручейки, которые свободно льются по широкому руслу без камней.',
            'Согласные — это плотины и камешки на пути ручейка, через которые вода весело перескакивает с хлопком или шорохом.',
            'Буква — это нарядное пальто или костюмчик, в который одевается невидимый звук, чтобы прийти в гости в тетрадь.'
          ],
          misconception: 'Дети часто называют букву «М» как [эм], а букву «К» как [ка], из-за чего читают слово «МАМА» как «ЭМАЭМА». Ловушка: буква имеет название («эм»), но произносить мы должны чистый короткий звук [м]. Буквы Е, Ё, Ю, Я — это буквы, а не отдельные чистые звуки.',
          rule: 'Воздух свободно течёт — гласный звук поёт! Преграда на пути — согласный звук ищи! Сколько в слове гласных — столько и слогов!',
          dialogueScript: 'Учитель: "Ребята, положите ладошку на горлышко и широко откройте рот: [а-а-а]. Что чувствует ладошка? Что делает язычок?"\nДети: "Горлышко дрожит, поёт! А рот открыт, ничего не мешает!"\nУчитель: "Верно, это гласный звук — голос льётся свободно! А теперь сомкните губы и произнесите: [м-м-м]. Получится ли спеть с открытым ртом?"\nДети: "Нет! Губы закрыли ворота воздуху!"\nУчитель: "Вот она — преграда! Значит, звук [м] — согласный! Запомните наш секрет..."',
          tableHeaders: ['Гласные звуки (воздух поёт)', 'Согласные звуки (есть преграда)'],
          wordBank: ['[а]', '[б]', '[о]', '[к]', '[у]', '[с]', '[и]', '[т]'],
          neznaykaMistake: 'Незнайка утверждает: "Звук [м] — гласный, потому что корова говорит Му-у-у, значит он поётся!"',
          neznaykaCorrection: 'Незнайка ошибся: в слоге МУ поётся гласный звук [у], а при произнесении [м] губы смыкаются и создают преграду, поэтому [м] — согласный!',
          cipherKey: {'1': 'А', '2': 'И', '3': 'С', '4': 'Т'},
          cipherCode: '1 - 2 - 3 - 4',
          cipherAnswer: 'АИСТ',
          trizChallenge: 'Найди слово из трёх букв, в котором ровно один гласный звук стоит посередине между двумя твёрдыми согласными звуками.',
          trizWords: ['дом', 'утка', 'окно', 'лист'],
          trizAnswer: 'дом (согласный [д] - гласный [о] - согласный [м])',
          calligraphyElements: 'Элементы: наклонная линия с закруглением внизу вправо («крючок»), плавный овал букв о, а.',
          teacherAnswers: '1. Образец: о — гласный, п — согласный; у — гласный, р — согласный; э — гласный, с — согласный. 2. Стрелки: [а]->Гласный, [м]->Согласный твёрдый, [у]->Гласный, [к\']->Согласный мягкий. 3. Раскраска: А,У,О,Ы,И — красные; Б,М,К,Д,Т — синие. 4. Таблица: Гласные: [а], [о], [у], [и]; Согласные: [б], [к], [с], [т]. 5. Ошибка Незнайки: губы сомкнуты, создают преграду. 7. Шифр: АИСТ. 8. ТРИЗ: слово ДОМ.',
        );

      case 'ru_syllables_stress':
        return const PedagogicalPackage(
          category: 'ru_syllables_stress',
          essence: 'Слог — это наименьшая произносительная единица речи, порция воздуха, выталкиваемая за один толчок легких. В русском языке слогообразующими являются исключительно гласные звуки. Сколько в слове гласных — ровно столько и слогов! Ударение — это выделение одного из слогов силой выдоха, длительностью звучания и высотой голоса. Ударение в русском языке подвижное и разноместное, оно способно менять значение слова (за́мок — замо́к, кру́жки — кружки́). При переносе слов нельзя разбивать слоги и нельзя оставлять одну букву на строке.',
          metaphors: [
            'Слоги — это ритмичные шаги великана или ступеньки лестницы, по которым поднимается голос.',
            'Гласный звук — это капитан корабля; сколько капитанов — столько отдельных кораблей-слогов плывет в слове.',
